import re

UNITS = {
    "d": 86400,
    "h": 3600,
    "m": 60,
    "s": 1,
}


def parse_duration(text):
    """Return the number of seconds in a duration string.

    Accepts one or more <number><unit> pairs (e.g. '1h30m', '2d', '0.5h').
    Fractional values are truncated to the nearest whole unit before summing.
    """
    pairs = re.findall(r'(\d+(?:\.\d+)?)([dhms])', text)
    if not pairs:
        raise ValueError(f"Invalid duration string: {text!r}")
    return sum(int(float(number)) * UNITS[unit] for number, unit in pairs)
